            dai.safeTransfer(address(gsp), initialBaseTokensSwapped);
            uint256 receivedQuoteTokens = gsp.sellBase(tapir);

          vm.stopPrank();

         // this is the tx will be sandwiched by the MEV trader
         vm.prank(MAINTAINER);
