        // User deposits and requests withdrawal
        uint256 depositAmt = 1000 ether;
        depositWNXM(depositAmt, wnxmWhale);

        uint256 userShares = stNxm.balanceOf(wnxmWhale);
        withdrawWNXM(userShares, wnxmWhale);

